SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 코드 객체 — 전부 VALID */
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('FN_SCP0104_GET_CAPA_VERSION', 'FN_SCP0104_GET_SPREAD_TITLE', 'PKG_SCP0104', 'T_FN_SCP0104_CAPA_VERSION_ROW', 'T_FN_SCP0104_CAPA_VERSION_TAB', 'T_FN_SCP0104_SPREAD_TITLE_ROW', 'T_FN_SCP0104_SPREAD_TITLE_TAB') ORDER BY 1, 2;

/* 2) 컴파일 오류 — 0건 */
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('FN_SCP0104_GET_CAPA_VERSION', 'FN_SCP0104_GET_SPREAD_TITLE', 'PKG_SCP0104', 'T_FN_SCP0104_CAPA_VERSION_ROW', 'T_FN_SCP0104_CAPA_VERSION_TAB', 'T_FN_SCP0104_SPREAD_TITLE_ROW', 'T_FN_SCP0104_SPREAD_TITLE_TAB') ORDER BY NAME, TYPE, SEQUENCE;

/* 3) GTT 구조 — 0건(사내와 다른 GTT 가 있으면 행) */
SELECT E.T AS TABLE_NAME
  FROM (SELECT 'GT_SCP0104_ASGN_ALL' T, 'VER_ID|VARCHAR2|40|||Y;VER_SEQ|NUMBER|0|3|0|Y;DIVISION_ID|VARCHAR2|120|||Y;COMPANY_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;FACTORY_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;OPERATION_ID|VARCHAR2|120|||Y;ELTR_LN_TP_CD|VARCHAR2|120|||Y;SITE_NAME|VARCHAR2|400|||Y;COMPANY_NAME|VARCHAR2|400|||Y;PLANT_NAME|VARCHAR2|400|||Y;FACTORY_NAME|VARCHAR2|400|||Y;LINE_NAME|VARCHAR2|400|||Y;LANE_QTY|NUMBER|0|20|10|Y;ITEM_ID|VARCHAR2|400|||Y;NICK_NAME|VARCHAR2|400|||Y;YYYYMM|VARCHAR2|24|||Y;ASSIGN_PRIORITY|NUMBER|0|20|10|Y;DUMMY_YN|VARCHAR2|4|||Y;VALID_YN|VARCHAR2|4|||Y;CREATED_BY|VARCHAR2|800|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|800|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASGN_CHG' T, 'VER_ID|VARCHAR2|40|||Y;VER_SEQ|NUMBER|0|3|0|Y;DIVISION_ID|VARCHAR2|120|||Y;COMPANY_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;FACTORY_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;OPERATION_ID|VARCHAR2|120|||Y;ELTR_LN_TP_CD|VARCHAR2|120|||Y;SITE_NAME|VARCHAR2|400|||Y;COMPANY_NAME|VARCHAR2|400|||Y;PLANT_NAME|VARCHAR2|400|||Y;FACTORY_NAME|VARCHAR2|400|||Y;LINE_NAME|VARCHAR2|400|||Y;LANE_QTY|NUMBER|0|20|10|Y;ITEM_ID|VARCHAR2|400|||Y;NICK_NAME|VARCHAR2|400|||Y;YYYYMM|VARCHAR2|24|||Y;ASSIGN_PRIORITY|NUMBER|0|20|10|Y;DUMMY_YN|VARCHAR2|4|||Y;VALID_YN|VARCHAR2|4|||Y;CREATED_BY|VARCHAR2|800|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|800|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_ASGN_TOKEN' T, 'SLOT_NO|NUMBER|0|3|0|Y;NR|NUMBER|0|9|0|Y;TOKEN|VARCHAR2|800|||Y' S FROM DUAL
