    UNION ALL SELECT 'GT_SCP0104_CAPA_LOSS' T, 'DIVISION_ID|VARCHAR2|30|||Y;PLANT_ID|VARCHAR2|30|||Y;LINE_ID|VARCHAR2|30|||Y;OPERATION_ID|VARCHAR2|30|||Y;ELTR_LN_TP_CD|VARCHAR2|30|||Y;MDL_NM|VARCHAR2|100|||Y;COMPANY_ID|VARCHAR2|30|||Y;SITE_ID|VARCHAR2|30|||Y;FACTORY_ID|VARCHAR2|30|||Y;MSR_TP_CD|VARCHAR2|30|||Y;YYYYMM|VARCHAR2|6|||Y;PFRSLT_NVL|NUMBER|0|||Y;BASE_NVL|NUMBER|0|||Y;MSR_GR_CD|VARCHAR2|30|||Y;MSR_NVL|NUMBER|0|||Y;CREATED_BY|VARCHAR2|600|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|600|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DATE_COLS' T, 'NR|NUMBER|0|9|0|Y;COLUMN_NAME|VARCHAR2|4000|||Y;COLUMN_VALUE|VARCHAR2|4000|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DATE_VALS' T, 'ROW_NR|NUMBER|0|9|0|Y;COL_NR|NUMBER|0|9|0|Y;COL_NAME|VARCHAR2|120|||Y;COL_VALUE|VARCHAR2|400|||Y;YYYYMM|VARCHAR2|24|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_DUMMY_LIVE' T, 'SRC_TP|VARCHAR2|4|||Y;CODE_TP|VARCHAR2|8|||Y;VAL|VARCHAR2|400|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_EQUIPMENT' T, 'COMPANY_ID|VARCHAR2|120|||Y;DIVISION_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;FACTORY_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;OPERATION_ID|VARCHAR2|120|||Y;EQUIPMENT_ID|VARCHAR2|400|||Y;EQUIPMENT_NAME|VARCHAR2|400|||Y;WIDE_ROLL_ENABLE_FLAG|VARCHAR2|4|||Y;ELTR_LN_TP_CD|VARCHAR2|120|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_EQUIP_TP_ASGN' T, 'COMPANY_ID|VARCHAR2|120|||Y;DIVISION_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;FACTORY_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;OPERATION_ID|VARCHAR2|120|||Y;ELTR_LN_TP_CD|VARCHAR2|120|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_LINE_MDL' T, 'DIVISION_ID|VARCHAR2|120|||Y;COMPANY_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;FACTORY_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;OPERATION_ID|VARCHAR2|120|||Y;ELTR_LN_TP_CD|VARCHAR2|120|||Y;ITEM_ID|VARCHAR2|400|||Y;NICK_NAME|VARCHAR2|400|||Y;SITE_NAME|VARCHAR2|400|||Y;COMPANY_NAME|VARCHAR2|400|||Y;PLANT_NAME|VARCHAR2|400|||Y;FACTORY_NAME|VARCHAR2|400|||Y;LINE_NAME|VARCHAR2|400|||Y;DUMMY_YN|VARCHAR2|4|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LINE_SOP' T, 'VER_ID|VARCHAR2|10|||Y;VER_SEQ|NUMBER|0|3|0|Y;DIVISION_ID|VARCHAR2|30|||Y;COMPANY_ID|VARCHAR2|30|||Y;SITE_ID|VARCHAR2|30|||Y;PLANT_ID|VARCHAR2|30|||Y;FACTORY_ID|VARCHAR2|30|||Y;LINE_ID|VARCHAR2|30|||Y;OPERATION_ID|VARCHAR2|30|||Y;ELTR_LN_TP_CD|VARCHAR2|30|||Y;VALID_YN|VARCHAR2|10|||Y;SOP_DT|VARCHAR2|30|||Y;SOP_YM|VARCHAR2|6|||Y;SOP_YEAR|VARCHAR2|4|||Y;SOP_DDN|NUMBER|0|||Y;BASE_DDN|NUMBER|0|||Y;SOP_DDN_YEAR|NUMBER|0|||Y;CREATED_BY|VARCHAR2|800|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|800|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LINE_SOP_TEMP' T, 'VER_ID|VARCHAR2|30|||Y;VER_SEQ|NUMBER|0|||Y;DIVISION_ID|VARCHAR2|30|||Y;COMPANY_ID|VARCHAR2|30|||Y;SITE_ID|VARCHAR2|30|||Y;PLANT_ID|VARCHAR2|30|||Y;FACTORY_ID|VARCHAR2|30|||Y;LINE_ID|VARCHAR2|30|||Y;OPERATION_ID|VARCHAR2|30|||Y;ELTR_LN_TP_CD|VARCHAR2|30|||Y;VALID_YN|VARCHAR2|10|||Y;SOP_DT|VARCHAR2|30|||Y;CREATED_BY|VARCHAR2|800|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|800|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0104_SCP_MST_CAPA_LOSS' T, 'DIVISION_ID|VARCHAR2|30|||Y;PLANT_ID|VARCHAR2|30|||Y;LINE_ID|VARCHAR2|30|||Y;OPERATION_ID|VARCHAR2|30|||Y;ELTR_LN_TP_CD|VARCHAR2|30|||Y;MDL_NM|VARCHAR2|100|||Y;COMPANY_ID|VARCHAR2|30|||Y;SITE_ID|VARCHAR2|30|||Y;FACTORY_ID|VARCHAR2|30|||Y;MSR_TP_CD|VARCHAR2|30|||Y;YYYYMM|VARCHAR2|6|||Y;PFRSLT_NVL|NUMBER|0|||Y;BASE_NVL|NUMBER|0|||Y;MSR_GR_CD|VARCHAR2|30|||Y;MSR_NVL|NUMBER|0|||Y;CREATED_BY|VARCHAR2|600|||Y;CREATION_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|600|||Y;LAST_UPDATE_DATE|DATE|0|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0104' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'P_SCP0104_GET_CAPA_LINE_ASSIGN_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_ASSIGN_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_SOP_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_SOP_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_ASSIGN_MDL_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_CAPA_LINE_ASSIGN_MDL_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_GET_SPREAD_TITLE' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_SAVE_CAPA_LINE_ASSIGN_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_SAVE_CAPA_LINE_ASSIGN_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_SAVE_CAPA_LINE_SOP_ASSEMBLY' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_SAVE_CAPA_LINE_SOP_ELTR' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0104_CHECK_NAME_ON_DUMMY_CODE' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ELTR' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'ASSEMBLY' SHT_NM, 'CHECK_NAME_ON_DUMMY_CODE' MNU_BTN_CD FROM DUAL
