    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ASSEMBLY' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_ELTR' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'LINE_ASSEMBLY' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'LINE_ELTR' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_MODEL_ASSEMBLY' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'SOP_MODEL_ELTR' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0104' MNU_ID, 'spreadTitle' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S;
SELECT 'SCM_ADM_PROC_M' AS TBL, '화면 PKG 프로시저 파라미터' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_PROC_M T WHERE NVL(TO_CHAR(T.PROC_NM), '~') = NVL(TO_CHAR(S.PROC_NM), '~') AND NVL(TO_CHAR(T.COL_NM), '~') = NVL(TO_CHAR(S.COL_NM), '~') AND NVL(TO_CHAR(T.COL_TP_CD), '~') = NVL(TO_CHAR(S.COL_TP_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
