    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_CHECK_NAME_ON_DUMMY_CODE' PROC_NM, 'debug_mode' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_CHECK_NAME_ON_DUMMY_CODE' PROC_NM, 'o_rc1' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_CHECK_NAME_ON_DUMMY_CODE' PROC_NM, 'o_result_cursor' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_CHECK_NAME_ON_DUMMY_CODE' PROC_NM, 'p_code_tp' COL_NM, 'IN' COL_TP_CD FROM DUAL
