    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_GET_CAPA_LINE_ASSEMBLY' PROC_NM, 'debug_mode' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_GET_CAPA_LINE_ASSEMBLY' PROC_NM, 'o_rc1' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_GET_CAPA_LINE_ASSEMBLY' PROC_NM, 'o_result_cursor' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_GET_CAPA_LINE_ASSEMBLY' PROC_NM, 'p_division_id' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0104.P_SCP0104_GET_CAPA_LINE_ASSEMBLY' PROC_NM, 'p_factory_id' COL_NM, 'IN' COL_TP_CD FROM DUAL
